void esp_hosted_wlan_set_link(bool up)
{
  FAR struct esp_hosted_wlan_s *priv = &g_esp_hosted_wlan;
  irqstate_t flags;

  if (!priv->initialized)
    {
      return;
    }

  flags = spin_lock_irqsave(&priv->rx_lock);
  priv->link_up = up;
  spin_unlock_irqrestore(&priv->rx_lock, flags);

  if (up)
