      netdev_lower_carrier_on(&priv->dev);
    }
  else
    {
      netdev_lower_carrier_off(&priv->dev);
      esp_hosted_wlan_free_rx_queue(priv);
    }
}

int esp_hosted_wlan_deinitialize(void)
